mapper.select:
SELECT FROM biz_ship s INNER JOIN biz_shipping_company sp ON sp.id = s.company_id AND sp.deleted = 0 WHERE s.deleted = 0
AND s.company_id = #{req.parentId}
AND (s.ship_name LIKE CONCAT('%', #{req.keyword}, '%') OR s.ship_no LIKE CONCAT('%', #{req.keyword}, '%') OR sp.company_name LIKE CONCAT('%', #{req.keyword}, '%'))
ORDER BY sp.company_name ASC, s.ship_name ASC LIMIT #{limit}
